-- =========================================================
-- MIGRATION V4 - Nouveau contenu (lot 7)
-- A executer APRES migration_v3.sql (et migration_v3_content.sql si tu
-- l'as deja fait). Ce script AJOUTE du contenu, il ne supprime rien.
--
-- Contenu ajoute :
--   - "Qui est-ce ?" dans manga (103 personnages) et jeux_ensemble
--     (29 personnalites) : nouveau sous-type de devinette.
--   - Contenu "hot" reserve au mode Couple (30 questions + 30 defis),
--     protege par la nouvelle colonne content_items.is_hot.
--   - +30 items dans chacune des 10 sous-categories existantes de
--     jeux_ensemble (defis_gages, enigmes, existentiel_jeu, farfelues,
--     petits_jeux_competitifs, petits_jeux_cooperatifs,
--     questions_souvenir, qui_de_nous_deux, souvenirs, tu_preferes).
-- =========================================================

alter table public.content_items add column if not exists is_hot boolean not null default false;

-- ---------------------------------------------------------
-- BUG (trouvé en audit) : le style de jeu (2.1, migration_v3) et le
-- filtre hot n'étaient jamais transmis pour les groupes de 2+ membres,
-- car ceux-ci passent TOUJOURS par le flux d'invitation (Inviter.tsx)
-- plutôt que par l'écran de config classique (Categorie.tsx), et
-- game_invitations n'avait pas de colonne pour les stocker.
-- ---------------------------------------------------------
alter table public.game_invitations add column if not exists style text;
alter table public.game_invitations add column if not exists hot boolean not null default false;

-- ---------------------------------------------------------
-- Filtre hot/normal (2.1 bis) : nouvelles versions des fonctions de
-- selection de contenu avec un parametre p_hot. Quand p_hot est faux
-- (par defaut), le contenu "hot" est exclu du tirage ; quand il est
-- vrai, SEUL le contenu hot est propose (bascule explicite depuis
-- l'ecran de configuration, uniquement visible en mode Couple).
-- ---------------------------------------------------------
create or replace function public.get_unseen_content_v3(
  p_category text,
  p_subcategory text,
  p_level text,
  p_mode text,
  p_couple_id uuid,
  p_user_id uuid,
  p_limit int,
  p_style text default null,
  p_hot boolean default false
)
returns setof public.content_items as $$
  select ci.* from public.content_items ci
  where ci.category = p_category
    and (p_subcategory is null or ci.subcategory = p_subcategory)
    and (p_level is null or ci.level = p_level)
    and ci.mode_scope in (p_mode, 'tous')
    and ci.is_hot = coalesce(p_hot, false)
    and (
      p_style is null
      or (p_style = 'quiz' and ci.type in ('qcm', 'vrai_faux', 'devinette'))
      or (p_style = 'reponse_libre' and ci.type = 'reponse_libre')
      or (p_style = 'enigme' and ci.content_type = 'enigme')
      or (p_style = 'tu_preferes' and ci.type = 'tu_preferes')
      or (p_style = 'discussion' and ci.type = 'discussion')
      or (p_style = 'defi' and ci.content_type = 'defi')
    )
    and not exists (
      select 1 from public.content_seen cs
      where cs.content_id = ci.id
        and (
          (p_couple_id is not null and cs.couple_id = p_couple_id)
          or (p_couple_id is null and cs.user_id = p_user_id)
        )
    )
  order by random()
  limit p_limit;
$$ language sql security definer;

create or replace function public.get_content_with_fallback_v3(
  p_category text,
  p_subcategory text,
  p_level text,
  p_mode text,
  p_couple_id uuid,
  p_user_id uuid,
  p_limit int,
  p_style text default null,
  p_hot boolean default false
)
returns setof public.content_items as $$
declare
  v_count int;
begin
  select count(*) into v_count from public.get_unseen_content_v3(p_category, p_subcategory, p_level, p_mode, p_couple_id, p_user_id, p_limit, p_style, p_hot);
  if v_count >= p_limit then
    return query select * from public.get_unseen_content_v3(p_category, p_subcategory, p_level, p_mode, p_couple_id, p_user_id, p_limit, p_style, p_hot);
  else
    return query
    select ci.* from public.content_items ci
    where ci.category = p_category
      and (p_subcategory is null or ci.subcategory = p_subcategory)
      and (p_level is null or ci.level = p_level)
      and ci.mode_scope in (p_mode, 'tous')
      and ci.is_hot = coalesce(p_hot, false)
      and (
        p_style is null
        or (p_style = 'quiz' and ci.type in ('qcm', 'vrai_faux', 'devinette'))
        or (p_style = 'reponse_libre' and ci.type = 'reponse_libre')
        or (p_style = 'enigme' and ci.content_type = 'enigme')
        or (p_style = 'tu_preferes' and ci.type = 'tu_preferes')
        or (p_style = 'discussion' and ci.type = 'discussion')
        or (p_style = 'defi' and ci.content_type = 'defi')
      )
    order by random()
    limit p_limit;
  end if;
end;
$$ language plpgsql security definer;

